<script lang="ts">
  import { open } from "@tauri-apps/plugin-dialog";
  import { Check, ImagePlus, Palette, Pencil, Plus, Trash2, X } from "lucide-svelte";
  import { assetUrl } from "$lib/api";
  import { STYLE_PRESETS, type StylePresetId } from "$lib/style-presets";
  import type { CustomArtStyle } from "$lib/library-types";
  let { arts, selected, onChange, onSelect }: { arts:CustomArtStyle[];selected:StylePresetId;onChange:(arts:CustomArtStyle[])=>void|Promise<void>;onSelect:(id:StylePresetId)=>void|Promise<void> }=$props();
  let editor=$state<CustomArtStyle>();
  function create(){editor={id:`art-${Date.now().toString(36)}`,name:"",description:"",prompt:"",thumbnail:"",createdAt:new Date().toISOString()};}
  function edit(art:CustomArtStyle){editor={...art};}
  async function chooseImage(){if(!editor)return;const selected=await open({multiple:false,filters:[{name:"Images",extensions:["png","jpg","jpeg","webp","gif"]}],title:"Choose an art preview"});if(typeof selected==="string")editor={...editor,thumbnail:selected};}
  async function save(){if(!editor?.name.trim()||!editor.prompt.trim())return;const cleaned={...editor,name:editor.name.trim(),description:editor.description.trim(),prompt:editor.prompt.trim()};await onChange(arts.some(item=>item.id===cleaned.id)?arts.map(item=>item.id===cleaned.id?cleaned:item):[cleaned,...arts]);editor=undefined;}
  async function remove(art:CustomArtStyle){if(window.confirm(`Delete ${art.name}?`)){await onChange(arts.filter(item=>item.id!==art.id));if(selected===art.id)await onSelect("pixel-rpg");}}
  function preview(path:string){return path.startsWith("/")?path:assetUrl(path);}
</script>

<section class="library"><header><div><span>VISUAL DIRECTIONS</span><h1>Arts</h1><p>Choose the project’s default art direction or add your own style with a reference image and production prompt.</p></div><button class="add" onclick={create}><Plus size={15}/>Add art</button></header>
  <div class="grid">
    {#each STYLE_PRESETS as art}<button class="card" class:selected={selected===art.id} onclick={()=>onSelect(art.id)}><img src={art.thumbnail} alt=""/><span class="copy"><strong>{art.name}</strong><small>{art.description}</small></span>{#if selected===art.id}<i><Check size={12}/></i>{/if}</button>{/each}
    {#each arts as art}<article class="card" class:selected={selected===art.id}><button class="select" onclick={()=>onSelect(art.id)} aria-label={`Use ${art.name}`}>{#if art.thumbnail}<img src={preview(art.thumbnail)} alt=""/>{:else}<span class="placeholder"><Palette size={24}/></span>{/if}<span class="copy"><strong>{art.name}</strong><small>{art.description||"Custom art direction"}</small></span></button>{#if selected===art.id}<i><Check size={12}/></i>{/if}<div class="actions"><button onclick={()=>edit(art)} title="Edit"><Pencil size={12}/></button><button onclick={()=>remove(art)} title="Delete"><Trash2 size={12}/></button></div></article>{/each}
    <button class="new-card" onclick={create}><ImagePlus size={22}/><strong>Add your art</strong><small>Reference image + style prompt</small></button>
  </div>
</section>

{#if editor}<div class="backdrop" role="presentation" onclick={(event)=>event.target===event.currentTarget&&(editor=undefined)}><form class="dialog" onsubmit={(event)=>{event.preventDefault();save();}}><header><div><span>CUSTOM ART</span><h2>{arts.some(item=>item.id===editor?.id)?"Edit art":"Add art"}</h2></div><button type="button" onclick={() => editor=undefined}><X size={15}/></button></header><label>Name<input bind:value={editor.name} placeholder="Painterly noir"/></label><label>Description<input bind:value={editor.description} placeholder="Short visual summary"/></label><label>Style prompt<textarea bind:value={editor.prompt} placeholder="Describe palette, linework, lighting, materials, and rendering…"></textarea></label><label>Preview image<div class="image-field"><input value={editor.thumbnail} readonly placeholder="Optional local image"/><button type="button" onclick={chooseImage}>Choose</button></div></label><footer><button type="button" onclick={() => editor=undefined}>Cancel</button><button class="primary" disabled={!editor.name.trim()||!editor.prompt.trim()}>Save art</button></footer></form></div>{/if}

<style>
  .library{height:100%;overflow:auto;padding:46px clamp(34px,6vw,84px);background:var(--bg)}.library>header{display:flex;align-items:flex-start;justify-content:space-between;gap:30px;padding-bottom:28px;border-bottom:1px solid var(--border)}header span{font-size:9px;letter-spacing:.15em;font-weight:700;color:var(--accent)}h1{font-size:28px;letter-spacing:-.035em;margin:7px 0 8px}header p{font-size:12px;line-height:1.5;color:var(--muted);margin:0;max-width:560px}.add,.primary{height:36px;border:1px solid var(--accent);border-radius:7px;background:var(--accent);color:#111;display:flex;align-items:center;gap:7px;padding:0 12px;font:inherit;font-size:11px;font-weight:650;cursor:pointer}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding-top:25px}.card,.new-card{position:relative;min-width:0;min-height:190px;border:1px solid var(--border);border-radius:9px;background:var(--sidebar);color:var(--text);overflow:hidden;text-align:left}.card{padding:0;cursor:pointer}.card:hover,.new-card:hover{border-color:var(--border-strong)}.card.selected{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent-dim)}.card>img,.select>img,.placeholder{width:100%;height:125px;object-fit:cover;background:var(--preview);display:grid;place-items:center;color:var(--faint)}.copy{display:block;padding:11px 12px}.copy strong,.copy small{display:block}.copy strong{font-size:12px}.copy small{font-size:10px;color:var(--muted);line-height:1.4;margin-top:4px}.card i{position:absolute;right:8px;top:8px;width:23px;height:23px;border-radius:50%;background:var(--accent);color:#111;display:grid;place-items:center}.select{width:100%;border:0;background:transparent;color:inherit;padding:0;text-align:left;cursor:pointer}.actions{position:absolute;right:6px;bottom:6px;display:flex;gap:2px}.actions button{width:27px;height:27px;border:0;border-radius:5px;background:var(--surface);color:var(--faint);display:grid;place-items:center;cursor:pointer}.actions button:hover{color:var(--text)}.new-card{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;border-style:dashed;color:var(--faint);cursor:pointer}.new-card strong{font-size:12px;color:var(--text)}.new-card small{font-size:10px}.backdrop{position:fixed;inset:0;z-index:60;background:#000a;display:grid;place-items:center}.dialog{width:min(520px,calc(100vw - 32px));background:var(--surface);border:1px solid var(--border-strong);border-radius:11px;padding:21px}.dialog header{display:flex;justify-content:space-between}.dialog h2{font-size:18px;margin:6px 0 0}.dialog header button{width:28px;height:28px;border:0;border-radius:5px;background:transparent;color:var(--faint);display:grid;place-items:center}.dialog label{display:block;font-size:10px;color:var(--muted);margin-top:14px}.dialog input,.dialog textarea{display:block;width:100%;margin-top:6px;border:1px solid var(--border-strong);border-radius:6px;background:var(--bg);color:var(--text);padding:9px;font:inherit;font-size:11px}.dialog input{height:37px}.dialog textarea{height:112px;resize:vertical}.image-field{display:flex;gap:7px}.image-field input{min-width:0;flex:1}.image-field button,.dialog footer>button:not(.primary){height:37px;margin-top:6px;border:1px solid var(--border);border-radius:6px;background:var(--bg);color:var(--muted);padding:0 11px;font:inherit;font-size:11px;cursor:pointer}.dialog footer{display:flex;justify-content:flex-end;gap:7px;margin-top:18px}.dialog footer>button:not(.primary){margin:0}.primary:disabled{opacity:.45}@media(max-width:1100px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:800px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
